// ───────────────────────── texto ─────────────────────────

/** minúsculas, sin tildes ni signos; «Perfúme, ÁRABE!» → «perfume arabe» */
export function normalizar(t) {
  return String(t || '')
    .toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/ñ/g, 'n')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

/** raíz por reglas simples: plural, diminutivo y vocal de género. «tortitas» → «tort», «sabores» → «sabor» */
export function raiz(p) {
  let w = p;
  if (w.length <= 3) return w;
  if (/ces$/.test(w) && w.length > 4) w = w.slice(0, -3) + 'z';             // luces → luz
  else if (/[aeiou]s$/.test(w)) w = w.slice(0, -1);                       // cremas → crema
  else if (/[^aeiou]es$/.test(w) && w.length > 5) w = w.slice(0, -2);     // sabores → sabor
  const dim = w.replace(/(c|qu)?it[oa]$/, (m, c) => (c === 'qu' ? 'c' : ''))  // tortita → tort, cafecito → cafe
               .replace(/isim[oa]$/, '');                                   // finísimo → fin
  if (dim.length >= 3) w = dim;
  if (w.length > 4) w = w.replace(/[aoe]$/, '');                          // dorada/dorado → dorad
  return w;
}

const ESPACIO = (s) => ' ' + s + ' ';

function prepararTexto(texto) {
  const norm = normalizar(texto);
  const tokens = norm ? norm.split(' ') : [];
  const raices = tokens.map(raiz);
  return { norm, tokens, raices, set: new Set(raices), frase: ESPACIO(raices.join(' ')) };
}

const cacheClave = new Map();
function claveDe(palabra) {
  let c = cacheClave.get(palabra);
  if (!c) {
    const toks = normalizar(palabra).split(' ').filter(Boolean);
    c = { multi: toks.length > 1, raices: toks.map(raiz) };
    c.frase = ESPACIO(c.raices.join(' '));
    cacheClave.set(palabra, c);
  }
  return c;
}

/** ¿aparece la palabra o frase (ya con raíces) en el texto? */
function aparece(t, palabra) {
  const c = claveDe(palabra);
  if (!c.raices.length) return false;
  return c.multi ? t.frase.includes(c.frase) : t.set.has(c.raices[0]);
}

