// ───────────────────────── color ─────────────────────────

export function hexARgb(h) {
  const x = h.replace('#', '');
  const n = parseInt(x.length === 3 ? x.split('').map((c) => c + c).join('') : x, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
export function rgbAHex([r, g, b]) {
  return '#' + [r, g, b].map((v) => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('').toUpperCase();
}
export function luminancia(hex) {
  const [r, g, b] = hexARgb(hex).map((v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
/** contraste WCAG 2.x entre dos hex (1–21) */
export function contraste(a, b) {
  const la = luminancia(a), lb = luminancia(b);
  return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
}
function rgbAHsl([r, g, b]) {
  r /= 255; g /= 255; b /= 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b); let h = 0, s = 0; const l = (max + min) / 2;
  if (max !== min) {
    const d = max - min; s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    h = max === r ? (g - b) / d + (g < b ? 6 : 0) : max === g ? (b - r) / d + 2 : (r - g) / d + 4; h /= 6;
  }
  return [h, s, l];
}
function hslARgb([h, s, l]) {
  if (s === 0) return [l * 255, l * 255, l * 255];
  const q = l < 0.5 ? l * (1 + s) : l + s - l * s, p = 2 * l - q;
  const f = (t) => { if (t < 0) t += 1; if (t > 1) t -= 1; return t < 1 / 6 ? p + (q - p) * 6 * t : t < 1 / 2 ? q : t < 2 / 3 ? p + (q - p) * (2 / 3 - t) * 6 : p; };
  return [f(h + 1 / 3) * 255, f(h) * 255, f(h - 1 / 3) * 255];
}
export function mezclar(a, b, t) {
  const x = hexARgb(a), y = hexARgb(b);
  return rgbAHex(x.map((v, i) => v + (y[i] - v) * t));
}
function saturacion(hex) { return rgbAHsl(hexARgb(hex))[1]; }
function esNeutro(hex) { const [, s, l] = rgbAHsl(hexARgb(hex)); return s < 0.12 || l < 0.07 || l > 0.95; }

/** aclara u oscurece (en HSL) hasta llegar al contraste mínimo contra `fondo` */
export function llevarAContraste(color, fondo, minimo) {
  if (contraste(color, fondo) >= minimo) return color;
  const hsl = rgbAHsl(hexARgb(color));
  const subir = luminancia(fondo) < 0.18;
  for (let i = 0; i < 60; i++) {
    hsl[2] = Math.max(0, Math.min(1, hsl[2] + (subir ? 0.015 : -0.015)));
    const c = rgbAHex(hslARgb(hsl));
    if (contraste(c, fondo) >= minimo) return c;
  }
  return subir ? '#FFFFFF' : '#000000';
}
function mejorTexto(fondo, candidatos, minimo = 4.5) {
  let mejor = candidatos[0], max = 0;
  for (const c of candidatos) { const k = contraste(c, fondo); if (k >= minimo) return c; if (k > max) { max = k; mejor = c; } }
  return mejor;
}

/** contraste de cada par que importa en un pack; `ok` si todo cumple AA */
export function verificarPaleta(p) {
  const pares = {
    texto_fondo: [p.texto, p.fondo, 4.5],
    texto_superficie: [p.texto, p.superficie, 4.5],
    texto_suave_fondo: [p.texto_suave, p.fondo, 4.5],
    acento_fondo: [p.acento, p.fondo, 3],
    sobre_acento: [p.sobre_acento, p.acento, 4.5],
    sobre_secundario: [p.sobre_secundario, p.secundario, 4.5],
  };
  const r = {}; let ok = true;
  for (const [k, [a, b, min]] of Object.entries(pares)) {
    const c = Math.round(contraste(a, b) * 100) / 100; r[k] = c; if (c < min) ok = false;
  }
  r.ok = ok;
  return r;
}

/** detecta colores nombrados en el texto, en orden de aparición */
export function detectarColores(texto) {
  const norm = ESPACIO(normalizar(texto));
  const hallados = [];
  let resto = norm;
  for (const [nombre, hex] of COLORES) {
    const base = nombre.split(' ');
    const ult = base[base.length - 1];
    // adjetivos en -o admiten género y número (dorada, negros); los sustantivos solo plural (rosas, lilas)
    const fin = /o$/.test(ult) && ult.length > 3 ? ult.slice(0, -1) + '(?:o|a|os|as)' : ult + '(?:s|es)?';
    const patron = new RegExp(' ' + (base.length > 1 ? base.slice(0, -1).join(' ') + ' ' : '') + fin + ' ', 'g');
    let m;
    while ((m = patron.exec(resto))) {
      hallados.push({ nombre, hex, pos: m.index });
      resto = resto.slice(0, m.index) + ' ' + '_'.repeat(m[0].length - 2) + ' ' + resto.slice(m.index + m[0].length);
      patron.lastIndex = 0;
    }
  }
  hallados.sort((a, b) => a.pos - b.pos);
  const vistos = new Set();
  return hallados.filter((c) => !vistos.has(c.hex) && vistos.add(c.hex)).map(({ nombre, hex }) => ({ nombre, hex }));
}

/**
 * Ajusta la paleta del pack a los colores que nombró el alumno sin romper AA.
 * Neutros oscuros → fondo (si el pack es oscuro o si dijo «negro»); neutros claros → fondo de packs claros;
 * el primer color con croma → acento; el segundo → secundario. Luego recalcula texto, texto suave y
 * «sobre_*» y empuja el acento hasta 3:1 contra el fondo.
 */
export function ajustarPaleta(paleta, colores, tono = 'claro') {
  const p = { ...paleta };
  const notas = [];
  if (!colores || !colores.length) return { paleta: p, notas };
  const oscuros = colores.filter((c) => luminancia(c.hex) < 0.05);
  const clarosNeutros = colores.filter((c) => luminancia(c.hex) > 0.6 && esNeutro(c.hex));
  const cromaticos = colores.filter((c) => !oscuros.includes(c) && !clarosNeutros.includes(c) && !(esNeutro(c.hex) && luminancia(c.hex) > 0.2));
  let fondoNuevo = null;
  if (oscuros.length && (tono === 'oscuro' || oscuros[0].nombre.startsWith('negro'))) {
    const o = oscuros[0];
    // negro: mantenemos el negro con matiz del pack si ya era oscuro (más rico que #111)
    fondoNuevo = luminancia(p.fondo) < 0.03 && o.nombre.startsWith('negro') ? p.fondo : mezclar(o.hex, p.fondo, 0.15);
    notas.push(`fondo → ${o.nombre}`);
  } else if (clarosNeutros.length) {
    const c = clarosNeutros[0];
    fondoNuevo = luminancia(p.fondo) > 0.6 ? mezclar(p.fondo, c.hex, 0.6) : c.hex;
    notas.push(`fondo → ${c.nombre}`);
  }
  if (fondoNuevo) {
    const oscuroAntes = luminancia(p.fondo) < 0.18;
    p.fondo = fondoNuevo;
    const oscuroAhora = luminancia(p.fondo) < 0.18;
    p.superficie = oscuroAhora ? mezclar(p.fondo, '#FFFFFF', 0.05) : mezclar(p.fondo, '#FFFFFF', 0.6);
    if (oscuroAntes !== oscuroAhora) {
      p.secundario = oscuroAhora ? mezclar(p.fondo, '#FFFFFF', 0.12) : mezclar(p.fondo, '#000000', 0.1);
    }
  }
  if (cromaticos[0]) {
    p.acento = cromaticos[0].hex;
    notas.push(`acento → ${cromaticos[0].nombre}`);
  }
  if (cromaticos[1]) {
    p.secundario = cromaticos[1].hex;
    notas.push(`secundario → ${cromaticos[1].nombre}`);
  } else if (oscuros.length && !oscuros[0].nombre.startsWith('negro') && luminancia(p.fondo) > 0.18) {
    p.secundario = oscuros[0].hex; notas.push(`secundario → ${oscuros[0].nombre}`);
  }
  // contraste
  const claro = '#F7F3EC', oscuro = '#15130F';
  p.texto = mejorTexto(p.fondo, [paleta.texto, claro, oscuro, '#FFFFFF', '#000000'], 7);
  if (contraste(p.texto, p.superficie) < 4.5) p.superficie = p.fondo;
  let suave = p.texto;
  for (let t = 0.5; t >= 0; t -= 0.05) { const c = mezclar(p.texto, p.fondo, t); if (contraste(c, p.fondo) >= 4.6) { suave = c; break; } }
  p.texto_suave = suave;
  const acentoAntes = p.acento;
  p.acento = llevarAContraste(p.acento, p.fondo, 3);
  if (p.acento !== acentoAntes) notas.push(`acento ajustado ${acentoAntes} → ${p.acento} para 3:1 sobre el fondo`);
  p.sobre_acento = mejorTexto(p.acento, ['#FFFFFF', oscuro, p.fondo, '#000000']);
  if (contraste(p.sobre_acento, p.acento) < 4.5) {
    // acento de luminancia media: lo oscurecemos (o aclaramos) hasta que el texto encima pase AA
    const hsl = rgbAHsl(hexARgb(p.acento));
    const bajar = luminancia(p.acento) < 0.3;
    for (let i = 0; i < 40 && contraste(p.sobre_acento, p.acento) < 4.5; i++) {
      hsl[2] += bajar ? -0.015 : 0.015; p.acento = rgbAHex(hslARgb(hsl));
      p.sobre_acento = mejorTexto(p.acento, ['#FFFFFF', oscuro, '#000000']);
    }
  }
  p.sobre_secundario = mejorTexto(p.secundario, [p.texto, '#FFFFFF', oscuro, '#000000']);
  return { paleta: p, notas };
}

// ───────────────────────── clasificador ─────────────────────────

function puntuarDiccionario(t, dic) {
  const r = {};
  for (const [clave, lista] of Object.entries(dic)) {
    let s = 0; const hits = [];
    for (const w of lista) if (aparece(t, w)) { const peso = claveDe(w).multi ? 1.5 : 1; s += peso; hits.push(w); }
    if (s) r[clave] = { puntos: s, palabras: hits };
  }
  return r;
}

const NOMBRES_COLOR = new Set(COLORES.map(([n]) => claveDe(n).frase));
const cacheDf = new WeakMap();
function frecuencias(cat) {
  let df = cacheDf.get(cat);
  if (!df) {
    df = new Map();
    for (const p of cat.packs) for (const w of new Set(p.palabras.map((x) => claveDe(x).frase))) df.set(w, (df.get(w) || 0) + 1);
    cacheDf.set(cat, df);
  }
  return df;
}

function distanciaColor(a, b) {
  const x = hexARgb(a), y = hexARgb(b);
  const rm = (x[0] + y[0]) / 2;
  return Math.sqrt((2 + rm / 256) * (x[0] - y[0]) ** 2 + 4 * (x[1] - y[1]) ** 2 + (2 + (255 - rm) / 256) * (x[2] - y[2]) ** 2);
}

const TONO_OSCURO = ['oscuro', 'noche', 'nocturno', 'dark', 'negro', 'misterioso', 'intenso'];
const TONO_CLARO = ['claro', 'luminoso', 'blanco', 'pastel', 'suave', 'fresco', 'aireado'];

/**
 * clasificar(texto, { catalogo }) → { pack, id, puntaje, confianza, rubro, estilo, colores, alternativas, motivos }
 * `pack` es una copia del pack ganador con `paleta` ya ajustada a los colores nombrados y `paleta_base` la original.
 */
export function clasificar(texto, opciones = {}) {
  const cat = opciones.catalogo || CATALOGO;
  if (!cat) throw new Error('estilos-clasificar: falta el catálogo (corre estilos/construir.mjs o pasa { catalogo })');
  const t = prepararTexto(texto);
  const rubros = puntuarDiccionario(t, RUBROS);
  const estilos = puntuarDiccionario(t, ESTILOS);
  const colores = detectarColores(texto);
  const pideOscuro = TONO_OSCURO.some((w) => aparece(t, w));
  const pideClaro = TONO_CLARO.some((w) => aparece(t, w));

  const df = frecuencias(cat);
  const tabla = cat.packs.map((pack) => {
    let s = 0; const motivos = [];
    pack.rubros.forEach((r, i) => {
      if (rubros[r]) { const v = 3 * rubros[r].puntos * (i === 0 ? 1 : 0.55); s += v; motivos.push(`rubro ${r} +${v.toFixed(1)}`); }
    });
    if (estilos[pack.estilo]) { const v = 2 * estilos[pack.estilo].puntos; s += v; motivos.push(`estilo ${pack.estilo} +${v.toFixed(1)}`); }
    for (const e of pack.estilos_secundarios || []) if (estilos[e]) { const v = 0.8 * estilos[e].puntos; s += v; motivos.push(`estilo ${e} +${v.toFixed(1)}`); }
    // los colores ya puntúan aparte (afinidad de paleta): aquí no se cuentan dos veces
    const propias = pack.palabras.filter((w) => !NOMBRES_COLOR.has(claveDe(w).frase) && aparece(t, w));
    // palabra exclusiva de un pack pesa 2; compartida por varios, cerca de 1
    if (propias.length) { const v = propias.reduce((a, w) => a + 0.8 + 1.2 / (df.get(claveDe(w).frase) || 1) + (claveDe(w).multi ? 0.9 : 0), 0); s += v; motivos.push(`palabras ${propias.join(', ')} +${v.toFixed(1)}`); }
    for (const c of colores) {
      const d = Math.min(...['fondo', 'secundario', 'acento'].map((k) => distanciaColor(c.hex, pack.paleta[k])));
      if (d < 120) { s += 1.2; motivos.push(`color ${c.nombre} +1.2`); } else if (d < 200) { s += 0.5; motivos.push(`color ${c.nombre} +0.5`); }
    }
    if (pideOscuro && pack.tono === 'oscuro') { s += 0.8; motivos.push('tono oscuro +0.8'); }
    if (pideClaro && pack.tono === 'claro') { s += 0.5; motivos.push('tono claro +0.5'); }
    s += (pack.prioridad || 0) * 0.01;
    return { pack, puntaje: Math.round(s * 100) / 100, motivos };
  }).sort((a, b) => b.puntaje - a.puntaje);

  let ganador = tabla[0];
  if (!ganador || ganador.puntaje < 0.5) ganador = tabla.find((x) => x.pack.id === (cat.por_defecto || 'minimal-galeria')) || tabla[0];
  const segundo = tabla.find((x) => x !== ganador);
  const confianza = ganador.puntaje <= 0 ? 0 : Math.min(1, Math.round((1 - (segundo ? segundo.puntaje / ganador.puntaje : 0) * 0.7) * 100) / 100);
  const top = (o) => Object.entries(o).sort((a, b) => b[1].puntos - a[1].puntos)[0]?.[0] || null;
  const rubro = top(rubros) || ganador.pack.rubros[0];
  const { paleta, notas } = ajustarPaleta(ganador.pack.paleta, colores, ganador.pack.tono);
  const pack = { ...ganador.pack, paleta, paleta_base: ganador.pack.paleta, contraste: verificarPaleta(paleta) };
  // fotos del rubro detectado primero, si el pack las tiene
  if (pack.fotos && rubro) pack.fotos = [...pack.fotos.filter((f) => f.includes('-' + rubro + '-')), ...pack.fotos.filter((f) => !f.includes('-' + rubro + '-'))];
  return {
    id: pack.id, pack, puntaje: ganador.puntaje, confianza, rubro, estilo: top(estilos) || pack.estilo,
    colores, ajustes: notas, motivos: ganador.motivos,
    alternativas: tabla.filter((x) => x !== ganador).slice(0, 3).map((x) => ({ id: x.pack.id, nombre: x.pack.nombre, puntaje: x.puntaje })),
  };
}

// ───────────────────────── uso en páginas ─────────────────────────

/** variables CSS de un pack (mismos nombres que estilos.css) */
export function variablesCSS(pack, cat = CATALOGO, base = '') {
  const p = pack.paleta, T = pack.tipos, R = (cat && cat.respaldo) || {};
  const fam = (x) => `'${x.familia}', ${R[x.respaldo] || 'serif'}`;
  const v = {
    '--e-fondo': p.fondo, '--e-superficie': p.superficie, '--e-secundario': p.secundario, '--e-texto': p.texto,
    '--e-texto-suave': p.texto_suave, '--e-acento': p.acento, '--e-sobre-acento': p.sobre_acento, '--e-sobre-secundario': p.sobre_secundario,
    '--e-f-titular': fam(T.titular), '--e-f-texto': fam(T.texto), '--e-f-detalle': fam(T.detalle || T.texto),
    '--e-titular-peso': String(T.titular.peso), '--e-titular-estilo': T.titular.estilo || 'normal',
    '--e-titular-tracking': T.titular.tracking || '0', '--e-titular-caja': T.titular.mayusculas ? 'uppercase' : 'none',
    '--e-titular-interlineado': String(T.titular.interlineado || 1), '--e-texto-peso': String(T.texto.peso),
    '--e-texto-interlineado': String(T.texto.interlineado || 1.5), '--e-detalle-peso': String((T.detalle || T.texto).peso),
    '--e-detalle-tracking': (T.detalle || {}).tracking || '0', '--e-detalle-caja': (T.detalle || {}).mayusculas ? 'uppercase' : 'none',
    '--e-detalle-estilo': (T.detalle || {}).estilo || 'normal', '--e-razon': String(T.escala.razon),
    '--e-radio': pack.radio, '--e-sombra': pack.sombra, '--e-grano': String(pack.grano || 0),
    '--e-textura': pack.textura ? `url("${base}${pack.textura.archivo}")` : 'none',
    '--e-textura-opacidad': String(pack.textura ? pack.textura.opacidad : 0), '--e-textura-mezcla': pack.textura ? pack.textura.mezcla : 'normal',
  };
  return v;
}

/** pone las variables del pack en un elemento (CSSOM: lo permite la CSP de las escenas) */
export function aplicarPack(el, pack, { base = '../../comun/', catalogo = CATALOGO } = {}) {
  const abs = typeof location !== 'undefined' ? new URL(base, location.href).href : base;
  for (const [k, v] of Object.entries(variablesCSS(pack, catalogo, abs))) el.style.setProperty(k, v);
  el.dataset.pack = pack.id;
  return el;
}

const fuentesCargadas = new Map();
/** carga las fuentes del pack con fetch + FontFace (la CSP de las escenas solo deja font-src data:) */
export function cargarFuentes(pack, { base = '../../comun/', catalogo = CATALOGO } = {}) {
  if (typeof FontFace === 'undefined' || typeof document === 'undefined') return Promise.resolve([]);
  const familias = new Set([pack.tipos.titular.familia, pack.tipos.texto.familia, pack.tipos.detalle && pack.tipos.detalle.familia].filter(Boolean));
  const tareas = [];
  for (const f of familias) {
    for (const d of (catalogo.fuentes[f] || [])) {
      const clave = f + '|' + d.archivo;
      if (!fuentesCargadas.has(clave)) {
        fuentesCargadas.set(clave, (async () => {
          try {
            const r = await fetch(base + d.archivo, { credentials: 'same-origin' });
            if (!r.ok) return false;
            const face = new FontFace(f, await r.arrayBuffer(), { weight: d.weight, style: d.style });
            await face.load(); document.fonts.add(face); return true;
          } catch (e) { return false; }
        })());
      }
      tareas.push(fuentesCargadas.get(clave));
    }
  }
  return Promise.all(tareas);
}

/** nombre de archivo de un icono Phosphor en el peso del pack: icono('whatsapp-logo', pack) → 'est-ico-whatsapp-logo-light.svg' */
export function icono(nombre, pack) {
  const peso = (pack && pack.iconos && pack.iconos.peso) || 'regular';
  return 'est-ico-' + nombre + (peso === 'regular' ? '' : '-' + peso) + '.svg';
}

export function pack(id, cat = CATALOGO) { return cat && cat.packs.find((p) => p.id === id) || null; }

if (typeof globalThis !== 'undefined') globalThis.EstilosJMD = { clasificar, pack, aplicarPack, cargarFuentes, icono, contraste, verificarPaleta, CATALOGO };
